SELECT analytics_order_facts.month, SUM(analytics_order_facts.gross_revenue) AS gross_revenue FROM analytics_order_facts WHERE analytics_order_facts.year IN (2026, 2022) AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'education' AND analytics_order_facts.category = 'category_10' AND analytics_order_facts.payment_method = 'bank_transfer' GROUP BY analytics_order_facts.month ORDER BY analytics_order_facts.month ASC LIMIT 24
